<?phpclass GoogleReferer {    public static function wooen_set_google_referer( int $postID, string $url ): void    {        if ( stripos( $url, 'google.com' ) !== false ) {            $key = '_wooen_plugin_referer_key_num';            if ( ! metadata_exists( 'post', $postID, $key ) ) {                add_post_meta( $postID, $key, 1, true );            } else {                $count = (int) get_post_meta( $postID, $key, true );                $count++;                update_post_meta( $postID, $key, $count );            }        }    }    public static function wooen_get_google_referer( int $postID ): int    {        $key = '_wooen_plugin_referer_key_num';        if ( ! metadata_exists( 'post', $postID, $key ) ) {            return 0;        }        return (int) get_post_meta( $postID, $key, true );    }}